#include <iostream>
#include <queue>
#include <string>
#include <vector>

std::vector<std::string> runQueue(const std::vector<std::string>& commands) {
    std::queue<std::string> queue;
    std::vector<std::string> served;
    for (const std::string& command : commands) {
        if (command == "serve") {
            if (queue.empty()) {
                served.push_back("empty");
            } else {
                served.push_back(queue.front());
                queue.pop();
            }
        } else {
            queue.push(command.substr(command.find(' ') + 1));
        }
    }
    return served;
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    int n = std::stoi(line);
    std::vector<std::string> commands;
    for (int i = 0; i < n; i++) {
        std::getline(std::cin, line);
        commands.push_back(line);
    }
    for (const std::string& out : runQueue(commands)) {
        std::cout << out << "\n";
    }
    return 0;
}

