package main

import (
	"bufio"
	"container/list"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func runQueue(commands []string) []string {
	queue := list.New()
	served := []string{}
	for _, command := range commands {
		if command == "serve" {
			front := queue.Front()
			if front == nil {
				served = append(served, "empty")
			} else {
				served = append(served, queue.Remove(front).(string))
			}
		} else {
			queue.PushBack(strings.Fields(command)[1])
		}
	}
	return served
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	n, _ := strconv.Atoi(strings.TrimSpace(scanner.Text()))
	commands := []string{}
	for i := 0; i < n && scanner.Scan(); i++ {
		commands = append(commands, strings.TrimSpace(scanner.Text()))
	}
	for _, line := range runQueue(commands) {
		fmt.Println(line)
	}
}
